package cn.lili.common.security.session;
import cn.lili.modules.community.p0.support.*;
import cn.lili.modules.community.p0.agreement.*;
import com.google.gson.JsonObject;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.time.*;
import java.util.*;
import static cn.lili.common.security.session.Stage1PersistenceTest.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@EnabledIfSystemProperty(named="s1.integration",matches="owned-run")
class Stage1CooperationCoverageTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh(){new Stage1PersistenceTest().freshManagerSessions();}
    static JsonObject rule(OwnerFixture owner,String agreement,LocalDate start,LocalDate end,String predecessor,int status)throws Exception{
        var terms=object(db.required("SELECT terms FROM li_p0_agreement WHERE id=?",agreement).get("terms"));return call(post(Stage1Routes.MANAGER+"/commission-rules"),channel,map("requestId",req(),"storeId",owner.store(),"agreementId",agreement,"businessType","MALL","predecessorId",predecessor,"payload",map("name","S1_TEST版本规则","rateBps",terms.get("rateBps"),"baseCode",AgreementService.BASE,"roundCode",AgreementService.ROUND,"startDate",start.toString(),"endDate",end.toString(),"commissionClause",terms.get("commissionClause"),"triggerBasis","ORDER_COMPLETED_NO_BLOCKING_AFTERSALE","executionIntent",false)),status);
    }
    @Test void agreementCreationReplayAndRevisionUniqueConstraintNeverDuplicateHistory()throws Exception{
        var owner=ownerFixture();var body=map("requestId",req(),"storeId",owner.store(),"businessType","MALL","payload",map("name","S1_TEST最小草稿"));var draft=call(post(Stage1Routes.MANAGER+"/agreements"),operator,body,200);assertEquals(draft,call(post(Stage1Routes.MANAGER+"/agreements"),operator,body,200));String id=draft.get("id").getAsString();assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_agreement WHERE store_id=?",owner.store()));body.put("payload",map("name","S1_TEST改内容"));call(post(Stage1Routes.MANAGER+"/agreements"),operator,body,409);
        var second=call(post(Stage1Routes.MANAGER+"/agreements"),operator,map("requestId",req(),"storeId",owner.store(),"businessType","MALL","payload",map()),200);assertThrows(org.springframework.dao.DuplicateKeyException.class,()->db.update("UPDATE li_p0_agreement SET agreement_no=(SELECT n FROM (SELECT agreement_no AS n FROM li_p0_agreement WHERE id=?) source),revision=1 WHERE id=?",id,second.get("id").getAsString()));assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_audit WHERE object_id=? AND action='agreement.create'",id));
    }
    @Test void futureRuleReplacementAndAbnormalOverlapAreDeterministicWithoutTouchingOriginalTerms()throws Exception{
        var owner=ownerFixture();LocalDate today=LocalDate.now(Stage1Rules.ZONE);String agreement=agreementFixture(owner,500,today,null);var first=rule(owner,agreement,today,today.plusDays(20),null,200);String old=first.get("id").getAsString();call(post(Stage1Routes.MANAGER+"/commission-rules/"+old+"/publish"),channel,map("requestId",req(),"expectedVersion",0),200);var before=db.required("SELECT terms,effective_from,effective_to,agreement_id,agreement_revision FROM li_p0_commission_rule WHERE id=?",old);
        var second=rule(owner,agreement,today.plusDays(7),today.plusDays(25),old,200);var competitor=rule(owner,agreement,today.plusDays(7),today.plusDays(25),old,200);String a=second.get("id").getAsString(),b=competitor.get("id").getAsString();var result=Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/commission-rules/"+a+"/publish",channel,map("requestId",req(),"expectedVersion",0)),new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/commission-rules/"+b+"/publish",channel,map("requestId",req(),"expectedVersion",0)));String winner=result.getFirst()==200?a:b;Instant cut=today.plusDays(7).atStartOfDay(Stage1Rules.ZONE).toInstant();
        assertEquals(old,id(commissions.findEffectiveRule(owner.store(),"MALL",cut.minusMillis(1)),"id"));assertEquals(winner,id(commissions.findEffectiveRule(owner.store(),"MALL",cut),"id"));assertNull(commissions.findEffectiveRule(owner.store(),"MALL",today.plusDays(26).atStartOfDay(Stage1Rules.ZONE).toInstant()));assertEquals(before,db.required("SELECT terms,effective_from,effective_to,agreement_id,agreement_revision FROM li_p0_commission_rule WHERE id=?",old));assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_cooperation_cutover WHERE previous_id=?",old));
        call(put(Stage1Routes.MANAGER+"/commission-rules/"+old+"/draft"),channel,map("requestId",req(),"expectedVersion",2,"payload",map("rateBps",1)),409);assertNotNull(commissions.getImmutableVersion(old,1));
        // A corrupt historical fixture must fail closed, not select the first row.
        var overlapping=rule(owner,agreement,today.plusDays(7),today.plusDays(25),null,200);String corrupt=overlapping.get("id").getAsString();try{db.update("UPDATE li_p0_commission_rule SET published_at=?,enabled=1,status='PUBLISHED' WHERE id=?",clock.instant(),corrupt);assertEquals("RULE_WINDOW_CONFLICT",assertThrows(Stage1Exception.class,()->commissions.findEffectiveRule(owner.store(),"MALL",cut)).code());assertTrue(object(eligibility.evaluate(owner.store(),category,cut)).get("reasons").toString().contains("RULE_WINDOW_CONFLICT"));}finally{db.update("UPDATE li_p0_commission_rule SET published_at=NULL,enabled=0,status='DRAFT' WHERE id=?",corrupt);}
        var disable=map("requestId",req(),"expectedVersion",1,"reason","S1_TEST关闭未来规则");var disabled=call(post(Stage1Routes.MANAGER+"/commission-rules/"+winner+"/disable"),channel,disable,200);assertEquals(disabled,call(post(Stage1Routes.MANAGER+"/commission-rules/"+winner+"/disable"),channel,disable,200));assertNull(commissions.findEffectiveRule(owner.store(),"MALL",cut));assertNotNull(commissions.getImmutableVersion(winner,db.count("SELECT revision FROM li_p0_commission_rule WHERE id=?",winner)));assertTrue((Boolean)eligibility.evaluate(owner.store(),category,null).get("BASIC_ELIGIBLE"));
    }
    @Test void agreementStatesTerminationReplayAndVersionReferencesStayExplicit()throws Exception{
        var owner=ownerFixture();LocalDate today=LocalDate.now(Stage1Rules.ZONE);var draft=createAgreement(owner,0,today.plusDays(7),null);String id=draft.get("id").getAsString();assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("BASIC_ELIGIBLE"));call(post(Stage1Routes.MANAGER+"/agreements/"+id+"/confirm"),owner.login().session(),map("requestId",req(),"expectedVersion",0),403);call(post(Stage1Routes.MANAGER+"/agreements/"+id+"/confirm"),operator,map("requestId",req(),"expectedVersion",0),200);assertFalse((Boolean)eligibility.evaluate(owner.store(),category,null).get("BASIC_ELIGIBLE"));Instant start=today.plusDays(7).atStartOfDay(Stage1Rules.ZONE).toInstant();assertFalse((Boolean)eligibility.evaluate(owner.store(),category,start.minusMillis(1)).get("BASIC_ELIGIBLE"));assertTrue((Boolean)eligibility.evaluate(owner.store(),category,start).get("BASIC_ELIGIBLE"));
        var r=rule(owner,id,today.plusDays(7),today.plusDays(15),null,200);String ruleId=r.get("id").getAsString();call(post(Stage1Routes.MANAGER+"/commission-rules/"+ruleId+"/publish"),channel,map("requestId",req(),"expectedVersion",0),200);var old=db.required("SELECT terms,file_refs,agreement_no,revision,effective_from,effective_to FROM li_p0_agreement WHERE id=?",id);String next=agreementFixture(owner,100,today.plusDays(10),id);assertEquals(old,db.required("SELECT terms,file_refs,agreement_no,revision,effective_from,effective_to FROM li_p0_agreement WHERE id=?",id));assertEquals(id,String.valueOf(db.required("SELECT agreement_id FROM li_p0_commission_rule WHERE id=?",ruleId).get("agreement_id")));assertEquals(2,db.count("SELECT revision FROM li_p0_agreement WHERE id=?",next));
        var nowOwner=ownerFixture();String current=agreementFixture(nowOwner,0,today.minusDays(2),null);var row=db.required("SELECT * FROM li_p0_agreement WHERE id=?",current);Instant confirmed=instant(row.get("confirmed_at"));assertFalse((Boolean)eligibility.evaluate(nowOwner.store(),category,confirmed.minusMillis(1)).get("BASIC_ELIGIBLE"));assertTrue((Boolean)eligibility.evaluate(nowOwner.store(),category,confirmed).get("BASIC_ELIGIBLE"));
        for(var actor:List.of(channel,nowOwner.login().session()))call(post(Stage1Routes.MANAGER+"/agreements/"+current+"/terminate"),actor,map("requestId",req(),"expectedVersion",1,"reason","S1_TEST无权"),403);call(post(Stage1Routes.MANAGER+"/agreements/"+current+"/terminate"),operator,map("requestId",req(),"expectedVersion",1,"reason"," "),422);var command=map("requestId",req(),"expectedVersion",1,"reason","S1_TEST结束当前合作");var ended=call(post(Stage1Routes.MANAGER+"/agreements/"+current+"/terminate"),operator,command,200);assertEquals(ended,call(post(Stage1Routes.MANAGER+"/agreements/"+current+"/terminate"),operator,command,200));var changed=new LinkedHashMap<>(command);changed.put("reason","S1_TEST改理由");call(post(Stage1Routes.MANAGER+"/agreements/"+current+"/terminate"),operator,changed,409);assertFalse((Boolean)eligibility.evaluate(nowOwner.store(),category,null).get("BASIC_ELIGIBLE"));assertEquals(row.get("terms"),db.required("SELECT terms FROM li_p0_agreement WHERE id=?",current).get("terms"));
    }
    @Test void ruleBusinessWindowAndFixedFormulaCannotBeInjectedAndReadPathsNeverWrite()throws Exception{
        var owner=ownerFixture();LocalDate today=LocalDate.now(Stage1Rules.ZONE);String agreement=agreementFixture(owner,500,today,null);var initial=rule(owner,agreement,today,today.plusDays(3),null,200);String id=initial.get("id").getAsString();var base=initial.getAsJsonObject("payload");
        for(var entry:Map.of("baseCode","PRODUCT_AND_SHIPPING","roundCode","HALF_UP","formula","total * percent").entrySet()){var payload=base.deepCopy();payload.addProperty(entry.getKey(),entry.getValue());call(put(Stage1Routes.MANAGER+"/commission-rules/"+id+"/draft"),channel,map("requestId",req(),"expectedVersion",0,"payload",payload),422);}
        call(post(Stage1Routes.MANAGER+"/commission-rules"),channel,map("requestId",req(),"storeId",owner.store(),"agreementId",agreement,"businessType","GROUP_BUY","payload",base),422);var beyond=rule(owner,agreement,today,today.plusYears(2),null,200);call(post(Stage1Routes.MANAGER+"/commission-rules/"+beyond.get("id").getAsString()+"/publish"),channel,map("requestId",req(),"expectedVersion",0),422);
        call(post(Stage1Routes.MANAGER+"/commission-rules/"+id+"/publish"),channel,map("requestId",req(),"expectedVersion",0),200);var before=Stage1SupplyMatrixTest.factCounts();forbidSqlWrites.set(true);try{for(int i=0;i<10;i++){assertNotNull(commissions.findEffectiveRule(owner.store(),"MALL",clock.instant()));assertNotNull(commissions.getImmutableVersion(id,1));var view=call(get(Stage1Routes.MANAGER+"/commission-rules/"+id),channel,null,200);assertFalse(view.get("fundExecutionEnabled").getAsBoolean());call(post(Stage1Routes.MANAGER+"/commission-rules/"+id+"/execute"),channel,map("requestId",req()),403);}}finally{forbidSqlWrites.remove();}assertEquals(before,Stage1SupplyMatrixTest.factCounts());
    }
}
